(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.MOBTWIG_COMMUNITY=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
 'use strict';
 const PUBLIC_KEY='mobtwig-community-v1',PROFILE_PREFIX='mobtwig-community-profile-v1:';
 const EMOTES=Object.freeze({wave:{name:'반가워요',src:'community-assets/emote-wave.svg'},cheer:{name:'응원해요',src:'community-assets/emote-cheer.svg'},think:{name:'생각 중',src:'community-assets/emote-think.svg'},thanks:{name:'고마워요',src:'community-assets/emote-thanks.svg'}});
 const FIXTURES=Object.freeze({workshop:{name:'달빛 공방 지도',src:'community-assets/workshop.svg'},garden:{name:'비 온 뒤 정원',src:'community-assets/garden.svg'}});
 const POLICY=Object.freeze({maxImages:3,inputBytes:2*1024*1024,imageDataChars:1400000,maxDimension:1024,postEmotes:8,commentEmotes:4,titleChars:100,bodyChars:10000,commentChars:2000});
 const uid=()=> 'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);
 const clone=value=>JSON.parse(JSON.stringify(value));
 const own=(value,key)=>Object.prototype.hasOwnProperty.call(value,key);
 const check=(condition,message)=>{if(!condition)throw new Error(message);};
 const object=value=>!!value&&typeof value==='object'&&!Array.isArray(value);
 const text=(value,max)=>typeof value==='string'&&value.length<=max;
 function createStore(storage,getMember,getWorks){
  const works=()=>getWorks().map(w=>({id:w.id,title:w.title,author:w.author,type:w.workType||'novel',chapters:w.chapters.length}));
  function boards(){return [...works().map(w=>({id:'work:'+w.id,type:'work',workId:w.id,title:w.title,subtitle:w.author,heads:['감상','질문','추측','자유']})),{id:'topic:reading',type:'topic',title:'독서 이야기',subtitle:'함께 나누는 읽는 일상',heads:['이야기','질문']},{id:'topic:writing',type:'topic',title:'창작 이야기',subtitle:'이야기를 만드는 과정',heads:['이야기','질문']},{id:'promotion',type:'promotion',title:'작품 홍보',subtitle:'새로운 이야기를 소개하는 별도 게시판',heads:['홍보']}];}
  const board=id=>boards().find(b=>b.id===id);
  function actor(expected){const member=getMember();check(member&&typeof member.id==='string'&&member.id&&expected===member.id,'로그인 계정이 변경되었거나 로그인이 필요합니다. 다시 열어 주세요.');return member;}
  function read(key,fallback){let raw;try{raw=storage.getItem(key);}catch{throw new Error('커뮤니티 저장 자료를 불러오지 못했습니다. 다시 시도해 주세요.');}if(raw===null)return fallback();try{return JSON.parse(raw);}catch{throw new Error('커뮤니티 저장 형식을 읽을 수 없습니다. 기존 자료는 보존했습니다.');}}
  function write(key,value){try{storage.setItem(key,JSON.stringify(value));}catch{throw new Error('저장하지 못했습니다. 입력과 이전 저장본은 유지됩니다. 저장 공간을 확인하고 다시 시도해 주세요.');}}
  function images(values){check(Array.isArray(values)&&values.length<=POLICY.maxImages,'시연에서는 본문 이미지 3장까지 사용할 수 있습니다.');const ids=new Set();return values.map(image=>{check(object(image)&&typeof image.id==='string'&&/^[a-zA-Z0-9_-]+$/.test(image.id)&&!ids.has(image.id),'이미지 식별자가 올바르지 않습니다.');ids.add(image.id);if(image.kind==='fixture'){check(own(FIXTURES,image.fixture),'허용된 시연 이미지만 사용할 수 있습니다.');return {id:image.id,kind:'fixture',fixture:image.fixture};}check(image.kind==='upload'&&typeof image.dataUrl==='string'&&/^data:image\/png;base64,iVBORw0KGgo[A-Za-z0-9+/=]+$/.test(image.dataUrl)&&image.dataUrl.length<=POLICY.imageDataChars&&Number.isInteger(image.width)&&Number.isInteger(image.height)&&image.width>0&&image.height>0&&image.width<=POLICY.maxDimension&&image.height<=POLICY.maxDimension&&text(image.name,120),'안전하게 변환된 PNG 이미지가 필요합니다.');return {id:image.id,kind:'upload',dataUrl:image.dataUrl,width:image.width,height:image.height,name:image.name};});}
  function emotes(values,max){check(Array.isArray(values)&&values.length<=max&&values.every(id=>typeof id==='string'&&own(EMOTES,id)),'허용된 이미지 이모티콘만 시연 개수 안에서 선택해 주세요.');return [...values];}
  function content(input,publishing=false){check(object(input),'작성 자료가 올바르지 않습니다.');const b=board(input.boardId);check(b,'게시판을 다시 선택해 주세요.');const linked=b.type==='work'?b.workId:(input.linkedWorkId||'');const w=works().find(w=>w.id===linked);check(!linked||w,'연결 작품을 다시 선택해 주세요.');check(b.type!=='promotion'||!!w,'홍보할 작품을 선택해 주세요.');check(text(input.title,POLICY.titleChars)&&text(input.body,POLICY.bodyChars),'시연 입력 길이를 초과했습니다.');if(publishing)check(input.title.trim()&&input.body.trim(),'제목과 본문을 입력해 주세요.');check(b.heads.includes(input.head),'이 게시판의 말머리를 선택해 주세요.');check(Number.isInteger(input.scope)&&input.scope>=0&&input.scope<=(w?.chapters||0),'스포일러 기준 작품과 범위를 확인해 주세요.');const media=images(input.images),emoticons=emotes(input.emotes,POLICY.postEmotes);check(input.representativeId===null||media.some(i=>i.id===input.representativeId),'대표이미지를 다시 선택해 주세요.');return {boardId:b.id,linkedWorkId:linked,title:input.title,body:input.body,head:input.head,scope:input.scope,images:media,emotes:emoticons,representativeId:input.representativeId};}
  function seed(){const rows=[],has=id=>works().some(w=>w.id===id),make=(id,boardId,title,body,extra={})=>({id,boardId,title,body,head:board(boardId).heads[0],linkedWorkId:board(boardId).workId||'',scope:0,images:[],emotes:[],representativeId:null,ownerId:'community-seed',name:'이야기산책',createdAt:1792972800000,...extra});if(has('moon')){rows.push(make('seed-moon-talk','work:moon','달빛 공방의 분위기가 좋았어요','물건의 기억을 읽는 설정이 인상적이었어요. 여러분은 어떤 장면이 마음에 남았나요?',{images:[{id:'sample-map',kind:'fixture',fixture:'workshop'}],representativeId:'sample-map',emotes:['wave']}));rows.push(make('seed-moon-spoiler','work:moon','은빛 서고에서 만난 세라의 약속','3화의 기록 관리인 세라와 은빛 서고에 대한 가상 토론입니다.',{head:'추측',scope:Math.min(3,works().find(w=>w.id==='moon').chapters),images:[{id:'secret-map',kind:'fixture',fixture:'workshop'}],representativeId:'secret-map',emotes:['think']}));}if(has('garden'))rows.push(make('seed-garden','work:garden','정원을 가꾸는 장면에 관해','느리게 마음을 나누는 장면이 좋았어요.',{images:[{id:'sample-garden',kind:'fixture',fixture:'garden'}],representativeId:'sample-garden'}));rows.push(make('seed-reading','topic:reading','요즘은 언제 책을 읽으세요?','잠들기 전 한 회차씩 읽는 시간을 만들고 있어요.',{emotes:['thanks']}));if(works()[0])rows.push(make('seed-promotion','promotion','이 이야기를 소개합니다','가상 작품을 소개하는 시연 홍보 글입니다. 실제 홍보 권한이나 빈도 정책은 별도입니다.',{linkedWorkId:works()[0].id}));return {version:1,posts:rows,comments:has('moon')?[{id:'seed-comment',postId:'seed-moon-talk',ownerId:'community-seed-b',name:'초록문장',body:'저도 공방 장면이 기억나요.',emotes:['cheer'],scope:0,createdAt:1792972900000}]:[]};}
  function publicState(){const state=read(PUBLIC_KEY,seed);check(object(state)&&state.version===1&&Array.isArray(state.posts)&&Array.isArray(state.comments),'커뮤니티 저장 형식이 올바르지 않습니다. 기존 자료는 보존했습니다.');const ids=new Set();for(const p of state.posts){check(object(p)&&typeof p.id==='string'&&!ids.has(p.id)&&typeof p.ownerId==='string'&&typeof p.name==='string'&&Number.isFinite(p.createdAt),'저장된 게시글 형식을 확인해 주세요.');ids.add(p.id);content(p,true);}const comments=new Set();for(const c of state.comments){check(object(c)&&typeof c.id==='string'&&!comments.has(c.id)&&ids.has(c.postId)&&typeof c.ownerId==='string'&&typeof c.name==='string'&&Number.isFinite(c.createdAt),'저장된 댓글 형식을 확인해 주세요.');comments.add(c.id);validateComment(c,state.posts.find(p=>p.id===c.postId));}return state;}
  function profile(){const member=getMember();if(!member)return {version:1,ownerId:null,favorites:[],opened:[],draft:null};const p=read(PROFILE_PREFIX+encodeURIComponent(member.id),()=>({version:1,ownerId:member.id,favorites:[],opened:[],draft:null}));check(object(p)&&p.version===1&&p.ownerId===member.id&&Array.isArray(p.favorites)&&p.favorites.every(id=>typeof id==='string')&&Array.isArray(p.opened)&&p.opened.every(id=>typeof id==='string'),'회원별 커뮤니티 자료를 읽을 수 없습니다. 기존 자료는 보존했습니다.');if(p.draft){check(p.draft.ownerId===member.id&&typeof p.draft.id==='string','다른 회원의 초안은 열 수 없습니다.');content(p.draft);}return p;}
  function updateProfile(expected,fn){const member=actor(expected),p=profile();fn(p);write(PROFILE_PREFIX+encodeURIComponent(member.id),p);return p;}
  const token=(kind,item)=>`${kind}:${item.id}:${item.scope}`;
  const allowed=(kind,item,p)=>!item.scope||p.opened.includes(token(kind,item));
  function projectPost(post,state,p){const base={id:post.id,boardId:post.boardId,linkedWorkId:post.linkedWorkId,scope:post.scope,name:post.name,createdAt:post.createdAt,commentCount:state.comments.filter(c=>c.postId===post.id).length,locked:!allowed('post',post,p)};return base.locked?base:{...base,title:post.title,body:post.body,head:post.head,images:clone(post.images),emotes:[...post.emotes],representativeId:post.representativeId};}
  function validateComment(input,post){check(Object.keys(input).every(key=>['body','emotes','scope','id','postId','ownerId','name','createdAt'].includes(key)),'댓글에는 일반 이미지를 첨부할 수 없습니다.');check(text(input.body,POLICY.commentChars),'시연 댓글 길이를 초과했습니다.');const icons=emotes(input.emotes,POLICY.commentEmotes);check(input.body.trim()||icons.length,'댓글 내용이나 이미지 이모티콘을 선택해 주세요.');const w=works().find(w=>w.id===post.linkedWorkId);check(Number.isInteger(input.scope)&&input.scope>=0&&input.scope<=(w?.chapters||0),'댓글의 스포일러 범위를 확인해 주세요.');return {body:input.body,emotes:icons,scope:input.scope};}
  return {
   boards,works,profile,
   list(boardId,query='',head='전체'){const state=publicState(),p=profile(),q=query.trim().toLocaleLowerCase();return state.posts.filter(post=>post.boardId===boardId).map(post=>projectPost(post,state,p)).filter(post=>(head==='전체'||!post.locked&&post.head===head)&&(!q||!post.locked&&[post.title,post.body].some(t=>t.toLocaleLowerCase().includes(q)))).sort((a,b)=>b.createdAt-a.createdAt||a.id.localeCompare(b.id));},
   post(id){const state=publicState(),post=state.posts.find(p=>p.id===id);check(post,'이 게시글을 찾을 수 없습니다.');return projectPost(post,state,profile());},
   comments(id){const state=publicState(),post=state.posts.find(p=>p.id===id),p=profile();check(post,'게시글을 찾을 수 없습니다.');if(!allowed('post',post,p))return [];return state.comments.filter(c=>c.postId===id).map(c=>allowed('comment',c,p)?{...clone(c),locked:false}:{id:c.id,postId:id,name:c.name,scope:c.scope,createdAt:c.createdAt,locked:true});},
   toggleFavorite(boardId,expected){check(board(boardId),'게시판을 다시 선택해 주세요.');return updateProfile(expected,p=>{p.favorites=p.favorites.includes(boardId)?p.favorites.filter(id=>id!==boardId):[...p.favorites,boardId];});},
   newDraft(boardId=''){const member=getMember();check(member,'로그인이 필요합니다.');const b=board(boardId)||boards()[0];check(b,'선택할 게시판이 없습니다.');return {id:uid(),ownerId:member.id,boardId:b.id,linkedWorkId:b.workId||(b.type==='promotion'?works()[0]?.id:'')||'',head:b.heads[0],title:'',body:'',images:[],emotes:[],representativeId:null,scope:0};},
   draft(){const p=profile();if(!p.draft)return null;return publicState().posts.some(post=>post.id===p.draft.id&&post.ownerId===p.ownerId)?null:clone(p.draft);},
   saveDraft(input,expected){const member=actor(expected);check(input.ownerId===member.id&&/^local-[a-zA-Z0-9-]+$/.test(input.id),'이 계정의 초안을 다시 열어 주세요.');const value={...content(input),id:input.id,ownerId:member.id};return updateProfile(expected,p=>{p.draft=value;});},
   publish(input,expected){const member=actor(expected);check(input.ownerId===member.id&&/^local-[a-zA-Z0-9-]+$/.test(input.id),'이 계정의 초안을 다시 열어 주세요.');const value=content(input,true),state=publicState(),old=state.posts.find(p=>p.id===input.id);if(old){check(old.ownerId===member.id,'다른 회원의 글을 변경할 수 없습니다.');return old.id;}state.posts.push({...value,id:input.id,ownerId:member.id,name:String(member.name||'독자'),createdAt:Date.now()});write(PUBLIC_KEY,state);return input.id;},
   addComment(id,input,expected){const member=actor(expected),state=publicState(),post=state.posts.find(p=>p.id===id);check(post,'게시글을 찾을 수 없습니다.');check(allowed('post',post,profile()),'스포일러 내용을 확인한 후 댓글을 작성해 주세요.');const value=validateComment(input,post),comment={...value,id:uid(),postId:id,ownerId:member.id,name:String(member.name||'독자'),createdAt:Date.now()};state.comments.push(comment);write(PUBLIC_KEY,state);return comment.id;},
   reveal(kind,id,confirmed,expected){check(confirmed===true,'스포일러 안내를 확인해 주세요.');const state=publicState(),item=kind==='post'?state.posts.find(p=>p.id===id):kind==='comment'?state.comments.find(c=>c.id===id):null;check(item,'확인할 내용을 찾을 수 없습니다.');return updateProfile(expected,p=>{if(kind==='comment'){const parent=state.posts.find(post=>post.id===item.postId);check(allowed('post',parent,p),'게시글 내용을 먼저 확인해 주세요.');}const key=token(kind,item);if(!p.opened.includes(key))p.opened.push(key);});}
  };
 }
 return Object.freeze({PUBLIC_KEY,PROFILE_PREFIX,EMOTES,FIXTURES,POLICY,createStore});
});
